    # Find separator rows (where all cells in the row are identical)
    sep_rows = [r for r in range(rows) if all(grid[r][c] == grid[r][0] for c in range(cols))]

    # Find separator columns (where all cells in the column are identical)
    sep_cols = [c for c in range(cols) if all(grid[r][c] == grid[0][c] for r in range(rows))]

    # Number of bands = separators + 1
    num_bands = len(sep_rows) + 1

    # Number of column regions = separators + 1
    num_col_regs = len(sep_cols) + 1

    # Marker value from test input (7)
    marker = 7

    output = []

    for band_idx in range(num_bands):
        # Determine band row boundaries
        band_start = sep_rows[band_idx] + 1 if band_idx < len(sep_rows) else 0
        if band_idx < len(sep_rows):
            band_end = sep_rows[band_idx + 1]
        else:
            band_end = rows

        band_row = []
        for col_idx in range(num_col_regs):
            # Determine column region boundaries
            if col_idx == 0:
                col_start = 0
            else:
                col_start = sep_cols[col_idx - 1] + 1

            if col_idx < len(sep_cols):
                col_end = sep_cols[col_idx]
            else:
                col_end = cols

            # Check if marker (7) is present in this region
            has_marker = any(
                grid[r][c] == marker
                for r in range(band_start, band_end)
                for c in range(col_start, col_end)
            )

            band_row.append(1 if has_marker else 0)
        output.append(band_row)

    return output
